import ast, hashlib, json
from pathlib import Path
root=Path('/workspace')
p=json.loads((root/'proposal.json').read_text())
r=json.loads((root/'runtime.json').read_text())
schema=r['study_schema']
def validate(value,s,path='"'$'"'):
    types={'object':dict,'array':list,'string':str,'integer':int,'number':(int,float),'boolean':bool}
    if 'type' in s:
        assert isinstance(value,types[s['type']]),(path,'type')
    if 'const' in s: assert value==s['const'],(path,'const')
    if 'enum' in s: assert value in s['enum'],(path,'enum')
    if isinstance(value,dict):
        assert set(s.get('required',[]))<=set(value),(path,'required')
        if s.get('additionalProperties') is False:
            assert set(value)<=set(s.get('properties',{})),(path,'additional')
        for k,v in value.items():
            if k in s.get('properties',{}):validate(v,s['properties'][k],path+'.'+k)
    if isinstance(value,list):
        assert len(value)>=s.get('minItems',0),(path,'minItems')
        for i,v in enumerate(value):validate(v,s.get('items',{}),path+'['+str(i)+']')
    if isinstance(value,str):assert len(value)>=s.get('minLength',0),(path,'minLength')
validate(p['study'],schema)
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert p['study']['evidence_refs']==['baseline-din']
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4
assert any(v['role']=='candidate' for v in p['variants'])
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert len({v['file'] for v in p['variants']})==len(p['variants'])
allowed={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
normalized=[]
for v in p['variants']:
    assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
    f=root/v['file'];source=f.read_text();tree=ast.parse(source,filename=str(f));compile(tree,str(f),'exec')
    imports=[]
    for n in ast.walk(tree):
        if isinstance(n,ast.Import):imports.extend(a.name.split('.')[0] for a in n.names)
        if isinstance(n,ast.ImportFrom):imports.append(n.module.split('.')[0])
        if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):
            assert n.func.id not in {'open','eval','exec','compile','__import__'},(v['name'],n.func.id)
    assert set(imports)<=allowed,(v['name'],imports)
    cfg=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
    assert all(cfg[k]==val for k,val in v['config'].items())
    model=next(n for n in tree.body if isinstance(n,ast.ClassDef) and n.name=='Model')
    init=next(n for n in model.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
    defaults=dict(zip([a.arg for a in init.args.args][-len(init.args.defaults):],init.args.defaults))
    assert all(ast.literal_eval(defaults[k])==val for k,val in v['config'].items())
    # Normalize only the literal factorial switches, leaving the full architecture.
    cfg_node=next(n for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
    for k,val in zip(cfg_node.value.keys,cfg_node.value.values):
        if ast.literal_eval(k) in {'task_specific','action_in_score'}:val.value=True
    for k in ['task_specific','action_in_score']:defaults[k].value=True
    normalized.append(ast.dump(tree))
    print(v['name'],'syntax/imports/config PASS','sha256='+hashlib.sha256(source.encode()).hexdigest())
assert len(set(normalized))==1,'Unexpected code difference between factorial cells'
assert hashlib.sha256((root/'baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
assert hashlib.sha256((root/'history_baseline_din.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
assert {a['knowledge_id'] for a in p['knowledge_assessments']}=={'unirank-method-infnet','unirank-method-mixformer'}
print('Study schema, protocol, evidence lineage, four-cell factorial, identical architecture and read-only references PASS')
print('Nominal dense parameter delta:',16*64+3*(32+1))
print('Estimated dense/total:',266213+16*64+3*(32+1),32059429+16*64+3*(32+1))
print('Training/forward/backward not executed; torch absent and host evaluation required')
PY"

